/* Generated additive CIMD checks. Run unchanged predecessor attestation first. */
SET NOCOUNT ON;
IF NOT EXISTS(SELECT 1 FROM sys.sql_modules m JOIN sys.objects o ON o.object_id=m.object_id JOIN sys.schemas s ON s.schema_id=o.schema_id
 WHERE o.object_id=OBJECT_ID(N'dbo.AiCimdReadAuthorizationReceiptsV1') AND o.type='P'
 AND COALESCE(o.principal_id,s.principal_id)=1 AND m.execute_as_principal_id=-2
 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND HASHBYTES('SHA2_256',m.definition)=0x535c60baf8c7d96f948381d11e5c30644aa07b081b34cb1e3eeb445c5f875993)
 OR EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id=OBJECT_ID(N'dbo.AiCimdReadAuthorizationReceiptsV1'))
 THROW 59520,'Metadata accessor source/owner/context drift.',1;
DECLARE @CimdEvidence table(BindingState nvarchar(max),ProofState nvarchar(max),ProofSource binary(32),ProofBefore binary(32),ProofCatalog binary(32),OAuthSource binary(32),OAuthBefore binary(32),OAuthCatalog binary(32));
INSERT @CimdEvidence EXEC dbo.AiCimdReadAuthorizationReceiptsV1;
IF (SELECT COUNT(*) FROM @CimdEvidence)<>1 THROW 59520,'Immutable evidence missing.',1;
DECLARE @C4aObjects table(Name sysname PRIMARY KEY); INSERT @C4aObjects VALUES (N'AiCimdFamilyV1'),(N'AiCimdCredentialV1'),(N'AiCimdInvocationV1'),(N'AiCimdProofControlV1'),(N'AiCimdProofReceiptV1'),(N'AiCimdDataLocateAccessOwnerV1'),(N'AiCimdDataLoadAuthorityV1'),(N'AiCimdDataAuthenticateV1'),(N'AiCimdDataAppendAccessV1'),(N'AiCimdDataAdmitV1'),(N'AiCimdDataSearchCasesV1'),(N'AiCimdDataGetCaseOverviewV1'),(N'AiCimdDataFinishCaseQuotaV1'),(N'AiCimdDataAuthorizeCaseHandoffV1'),(N'AiCimdDataRecordCaseFailureV1'),(N'AiCimdDataImmutableInvocation'),(N'AiCimdImmutableFamilyV1'),(N'AiCimdImmutableCredentialV1'),(N'AiCimdLifecycle_CredentialV1'),(N'AiCimdRevokeFamilyV1'),(N'AiCimdImmutableReceiptV1');
DECLARE @C4aOldState nvarchar(max)=(SELECT class,major_id,minor_id,name,CONVERT(varchar(max),CONVERT(varbinary(max),value),2) AS ReceiptValue FROM sys.extended_properties WHERE name LIKE 'Shale.%' AND NOT(class=1 AND OBJECT_NAME(major_id) IN(SELECT Name FROM @C4aObjects)) ORDER BY class,major_id,minor_id,name FOR XML PATH('r'),TYPE).value('.','nvarchar(max)');
SET @C4aOldState=@C4aOldState+(SELECT BindingState FROM @CimdEvidence);
DECLARE @C4aBefore binary(32)=HASHBYTES('SHA2_256',@C4aOldState);
DECLARE @C4aModules table(Name sysname PRIMARY KEY,Hash binary(32),OwnerLookup bit); INSERT @C4aModules VALUES (N'AiCimdDataLocateAccessOwnerV1',0x6c358f5c58362a3ca79303ae4bc4296f4772349216743862be3fa17a36f3b67f,1),(N'AiCimdDataLoadAuthorityV1',0x8e3907c529e7a9c9241c1cc5a47b0812b004856e87ee3bef71f1869852b82bc7,0),(N'AiCimdDataAuthenticateV1',0x5da2096e5f92f54033fc058b2fd710e7fe72f2c8b883f7b6e0ed64096c5fbe36,0),(N'AiCimdDataAppendAccessV1',0x8cbdbb3e875d2757571f3c2db4d64289cc0805742cf51b09296e20b88b265333,0),(N'AiCimdDataAdmitV1',0x3a8f1f250bbfaf5981ab7373dbeef07fe8162f58cb65162737ab88fc0434872e,0),(N'AiCimdDataSearchCasesV1',0x142505fa5fd4c3fb9574afa670af2303e8192b3d0dac9f3657b2eb4935661cf3,0),(N'AiCimdDataGetCaseOverviewV1',0xb99848d7a8e2b8ae75635cea0b02067ba42cbae7def13916fc9813c0bdf1013f,0),(N'AiCimdDataFinishCaseQuotaV1',0xb40ceade881d455d4b399d3a254737ced92379adf25f7ef0024621b7e9c4b868,0),(N'AiCimdDataAuthorizeCaseHandoffV1',0xe31f7b3de78a951d6115057543b764ab2f881dbd8747165f0bc4432b355afd6e,0),(N'AiCimdDataRecordCaseFailureV1',0xc36fe5be62a5f47dbdd707200b9c8ff19ceaf5ea006952a347be59b052fabef8,0),(N'AiCimdDataImmutableInvocation',0xf8be9680b7baae5b780d1d9af85bddc215596bca774531e441bc41aa0640f52b,0),(N'AiCimdImmutableFamilyV1',0x6f57d0cd6f0942cd7d577b212e27f6e4e2008dae87f0e816c9dfe04b8181d852,0),(N'AiCimdImmutableCredentialV1',0x21443ac7c353dd83327a690260162835b770d232c11cfbacd0ada397012ac808,0),(N'AiCimdLifecycle_CredentialV1',0x10c80b55f931b54600a032593ebe674ad3e6758062a75b2e991b0abff62eeedd,0),(N'AiCimdRevokeFamilyV1',0xb2c491da48cbf8f7099aa1e488aa89d3275369610817a4e6f6d4aabc179f2b27,0),(N'AiCimdImmutableReceiptV1',0xa0bf04f6e6687307d15c46292d3b9102dedb264b37c986a797430ec1a25119ff,0);
IF EXISTS(SELECT 1 FROM @C4aModules e WHERE NOT EXISTS(SELECT 1 FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id JOIN sys.sql_modules m ON m.object_id=o.object_id WHERE s.name='dbo' AND o.name=e.Name AND COALESCE(o.principal_id,s.principal_id)=1 AND m.uses_ansi_nulls=1 AND m.uses_quoted_identifier=1 AND ((e.OwnerLookup=1 AND m.execute_as_principal_id=-2) OR (e.OwnerLookup=0 AND m.execute_as_principal_id IS NULL)) AND HASHBYTES('SHA2_256',m.definition)=e.Hash)) THROW 59400,'CIMD proof module source/owner/context drift.',1;
IF EXISTS(SELECT 1 FROM sys.objects o JOIN sys.schemas s ON s.schema_id=o.schema_id WHERE s.name='dbo' AND o.name IN(SELECT Name FROM @C4aObjects) AND COALESCE(o.principal_id,s.principal_id)<>1)
 THROW 59400,'CIMD object ownership drift.',1;
IF EXISTS(SELECT 1 FROM sys.triggers t WHERE OBJECT_NAME(t.parent_id) IN(SELECT Name FROM @C4aObjects) AND t.name NOT IN(SELECT Name FROM @C4aModules))
 OR EXISTS(SELECT 1 FROM sys.sql_expression_dependencies d JOIN sys.objects o ON o.object_id=d.referencing_id WHERE (o.name IN(SELECT Name FROM @C4aObjects) AND o.type='U' OR o.type IN('C','D') AND OBJECT_NAME(o.parent_object_id) IN(SELECT Name FROM @C4aObjects)) AND (d.referenced_server_name IS NOT NULL OR d.referenced_database_name IS NOT NULL OR EXISTS(SELECT 1 FROM sys.objects f WHERE f.object_id=d.referenced_id AND f.type IN('FN','IF','TF','FS','FT','P','PC','SN'))))
 THROW 59400,'Unreviewed CIMD trigger/table-expression edge.',1;
IF (SELECT COUNT(*) FROM sys.security_predicates p JOIN sys.security_policies sp ON sp.object_id=p.object_id WHERE OBJECT_NAME(p.target_object_id) IN('AiCimdFamilyV1','AiCimdCredentialV1','AiCimdInvocationV1') AND sp.object_id=OBJECT_ID('sec.TenantFilter') AND sp.is_enabled=1 AND sp.is_schema_bound=1 AND p.predicate_definition COLLATE Latin1_General_100_BIN2=N'([sec].[fn_FilterByTenant]([ShaleClientId]))')<>9
 OR (SELECT COUNT(*) FROM sys.security_predicates WHERE OBJECT_NAME(target_object_id) IN('AiCimdFamilyV1','AiCimdCredentialV1','AiCimdInvocationV1'))<>9
 THROW 59400,'CIMD strict RLS drift.',1;
DECLARE @C4aPermissions table(RoleName sysname COLLATE Latin1_General_100_BIN2,ObjectName sysname COLLATE Latin1_General_100_BIN2,PermissionName sysname COLLATE Latin1_General_100_BIN2,State char(1) COLLATE Latin1_General_100_BIN2); INSERT @C4aPermissions VALUES (N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'SELECT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'INSERT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'UPDATE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'DELETE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'ALTER',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdFamilyV1',N'CONTROL',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'SELECT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'INSERT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'UPDATE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'DELETE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'ALTER',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdCredentialV1',N'CONTROL',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'SELECT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'INSERT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'UPDATE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'DELETE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'ALTER',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdInvocationV1',N'CONTROL',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'SELECT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'INSERT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'UPDATE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'DELETE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'ALTER',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofControlV1',N'CONTROL',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofReceiptV1',N'SELECT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofReceiptV1',N'INSERT',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofReceiptV1',N'UPDATE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofReceiptV1',N'DELETE',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofReceiptV1',N'ALTER',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdProofReceiptV1',N'CONTROL',N'D'),(N'AiCimdLifecycleV1',N'AiCimdFamilyV1',N'SELECT',N'D'),(N'AiCimdLifecycleV1',N'AiCimdFamilyV1',N'INSERT',N'D'),(N'AiCimdLifecycleV1',N'AiCimdFamilyV1',N'UPDATE',N'D'),(N'AiCimdLifecycleV1',N'AiCimdFamilyV1',N'DELETE',N'D'),(N'AiCimdLifecycleV1',N'AiCimdFamilyV1',N'ALTER',N'D'),(N'AiCimdLifecycleV1',N'AiCimdFamilyV1',N'CONTROL',N'D'),(N'AiCimdLifecycleV1',N'AiCimdCredentialV1',N'SELECT',N'D'),(N'AiCimdLifecycleV1',N'AiCimdCredentialV1',N'INSERT',N'D'),(N'AiCimdLifecycleV1',N'AiCimdCredentialV1',N'UPDATE',N'D'),(N'AiCimdLifecycleV1',N'AiCimdCredentialV1',N'DELETE',N'D'),(N'AiCimdLifecycleV1',N'AiCimdCredentialV1',N'ALTER',N'D'),(N'AiCimdLifecycleV1',N'AiCimdCredentialV1',N'CONTROL',N'D'),(N'AiCimdLifecycleV1',N'AiCimdInvocationV1',N'SELECT',N'D'),(N'AiCimdLifecycleV1',N'AiCimdInvocationV1',N'INSERT',N'D'),(N'AiCimdLifecycleV1',N'AiCimdInvocationV1',N'UPDATE',N'D'),(N'AiCimdLifecycleV1',N'AiCimdInvocationV1',N'DELETE',N'D'),(N'AiCimdLifecycleV1',N'AiCimdInvocationV1',N'ALTER',N'D'),(N'AiCimdLifecycleV1',N'AiCimdInvocationV1',N'CONTROL',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofControlV1',N'SELECT',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofControlV1',N'INSERT',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofControlV1',N'UPDATE',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofControlV1',N'DELETE',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofControlV1',N'ALTER',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofControlV1',N'CONTROL',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofReceiptV1',N'SELECT',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofReceiptV1',N'INSERT',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofReceiptV1',N'UPDATE',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofReceiptV1',N'DELETE',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofReceiptV1',N'ALTER',N'D'),(N'AiCimdLifecycleV1',N'AiCimdProofReceiptV1',N'CONTROL',N'D'),(N'AiCimdCaseRuntimeV1',N'AiCimdDataAuthenticateV1',N'EXECUTE',N'G'),(N'AiCimdCaseRuntimeV1',N'AiCimdDataSearchCasesV1',N'EXECUTE',N'G'),(N'AiCimdCaseRuntimeV1',N'AiCimdDataGetCaseOverviewV1',N'EXECUTE',N'G'),(N'AiCimdCaseRuntimeV1',N'AiCimdDataFinishCaseQuotaV1',N'EXECUTE',N'G'),(N'AiCimdCaseRuntimeV1',N'AiCimdDataAuthorizeCaseHandoffV1',N'EXECUTE',N'G'),(N'AiCimdCaseRuntimeV1',N'AiCimdDataRecordCaseFailureV1',N'EXECUTE',N'G'),(N'AiCimdLifecycleV1',N'AiCimdRevokeFamilyV1',N'EXECUTE',N'G');
IF EXISTS(SELECT USER_NAME(p.grantee_principal_id) COLLATE Latin1_General_100_BIN2,OBJECT_NAME(p.major_id) COLLATE Latin1_General_100_BIN2,p.permission_name COLLATE Latin1_General_100_BIN2,p.state COLLATE Latin1_General_100_BIN2 FROM sys.database_permissions p WHERE p.grantee_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdCaseRuntimeV1'),DATABASE_PRINCIPAL_ID('AiCimdLifecycleV1')) EXCEPT SELECT RoleName,ObjectName,PermissionName,State FROM @C4aPermissions)
 OR EXISTS(SELECT RoleName,ObjectName,PermissionName,State FROM @C4aPermissions EXCEPT SELECT USER_NAME(p.grantee_principal_id) COLLATE Latin1_General_100_BIN2,OBJECT_NAME(p.major_id) COLLATE Latin1_General_100_BIN2,p.permission_name COLLATE Latin1_General_100_BIN2,p.state COLLATE Latin1_General_100_BIN2 FROM sys.database_permissions p WHERE p.grantee_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdCaseRuntimeV1'),DATABASE_PRINCIPAL_ID('AiCimdLifecycleV1')))
 OR EXISTS(SELECT 1 FROM sys.database_permissions p WHERE p.grantee_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdCaseRuntimeV1'),DATABASE_PRINCIPAL_ID('AiCimdLifecycleV1')) AND (p.class<>1 OR p.minor_id<>0 OR p.grantor_principal_id<>1 OR OBJECT_SCHEMA_NAME(p.major_id)<>'dbo'))
 THROW 59400,'CIMD exact role permission drift.',1;

DECLARE @C4aCatalog nvarchar(max)=N'';
SET @C4aCatalog=@C4aCatalog+(SELECT CONCAT(o.name,N':',o.type,N':',o.principal_id,N':',m.execute_as_principal_id,N':',m.uses_ansi_nulls,N':',m.uses_quoted_identifier,N':',m.definition,N';') AS [text()] FROM sys.objects o LEFT JOIN sys.sql_modules m ON m.object_id=o.object_id WHERE o.schema_id=SCHEMA_ID('dbo') AND o.name IN(SELECT Name FROM @C4aObjects) ORDER BY o.name FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4aCatalog=@C4aCatalog+(SELECT CONCAT(OBJECT_NAME(c.object_id),N':',c.column_id,N':',c.name,N':',c.user_type_id,N':',c.max_length,N':',c.is_nullable,N':',c.is_identity,N':',c.collation_name,N';') AS [text()] FROM sys.columns c WHERE OBJECT_NAME(c.object_id) IN(SELECT Name FROM @C4aObjects) ORDER BY c.object_id,c.column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4aCatalog=@C4aCatalog+(SELECT CONCAT(OBJECT_NAME(o.parent_object_id),N':',o.name,N':',o.type,N':',ch.definition,N':',ch.is_disabled,N':',ch.is_not_trusted,N':',dc.definition,N':',fk.referenced_object_id,N':',fk.is_disabled,N':',fk.is_not_trusted,N':',fk.delete_referential_action,N':',fk.update_referential_action,N';') AS [text()] FROM sys.objects o LEFT JOIN sys.check_constraints ch ON ch.object_id=o.object_id LEFT JOIN sys.default_constraints dc ON dc.object_id=o.object_id LEFT JOIN sys.foreign_keys fk ON fk.object_id=o.object_id WHERE OBJECT_NAME(o.parent_object_id) IN(SELECT Name FROM @C4aObjects) ORDER BY o.object_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4aCatalog=@C4aCatalog+(SELECT CONCAT(f.constraint_object_id,N':',f.constraint_column_id,N':',f.parent_column_id,N':',f.referenced_column_id,N';') AS [text()] FROM sys.foreign_key_columns f WHERE OBJECT_NAME(f.parent_object_id) IN(SELECT Name FROM @C4aObjects) ORDER BY f.constraint_object_id,f.constraint_column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4aCatalog=@C4aCatalog+(SELECT CONCAT(i.object_id,N':',i.name,N':',i.is_unique,N':',i.is_disabled,N':',i.filter_definition,N':',c.column_id,N':',c.key_ordinal,N':',c.is_included_column,N';') AS [text()] FROM sys.indexes i JOIN sys.index_columns c ON c.object_id=i.object_id AND c.index_id=i.index_id WHERE OBJECT_NAME(i.object_id) IN(SELECT Name FROM @C4aObjects) ORDER BY i.object_id,i.index_id,c.index_column_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4aCatalog=@C4aCatalog+(SELECT CONCAT(p.target_object_id,N':',p.object_id,N':',p.predicate_definition,N':',p.predicate_type,N':',p.operation,N';') AS [text()] FROM sys.security_predicates p WHERE OBJECT_NAME(p.target_object_id) IN(SELECT Name FROM @C4aObjects) ORDER BY p.target_object_id,p.security_predicate_id FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4aCatalog=@C4aCatalog+(SELECT CONCAT(p.class,N':',p.major_id,N':',p.minor_id,N':',p.grantee_principal_id,N':',p.grantor_principal_id,N':',p.permission_name,N':',p.state,N';') AS [text()] FROM sys.database_permissions p WHERE p.class=1 AND OBJECT_NAME(p.major_id) IN(SELECT Name FROM @C4aObjects) OR p.grantee_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdCaseRuntimeV1'),DATABASE_PRINCIPAL_ID('AiCimdLifecycleV1')) ORDER BY p.class,p.major_id,p.minor_id,p.grantee_principal_id,p.permission_name FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
SET @C4aCatalog=@C4aCatalog+(SELECT CONCAT(t.name,N':',t.parent_id,N':',t.is_disabled,N':',t.is_instead_of_trigger,N':',e.type,N':',e.is_first,N':',e.is_last,N':',m.definition,N';') AS [text()] FROM sys.triggers t LEFT JOIN sys.trigger_events e ON e.object_id=t.object_id LEFT JOIN sys.sql_modules m ON m.object_id=t.object_id WHERE OBJECT_NAME(t.parent_id) IN(SELECT Name FROM @C4aObjects) ORDER BY t.object_id,e.type FOR XML PATH(''),TYPE).value('.','nvarchar(max)');
DECLARE @C4aFingerprint binary(32)=HASHBYTES('SHA2_256',@C4aCatalog);

IF ISNULL((SELECT ProofSource FROM @CimdEvidence),0x)<>0x6ad3d47b5cfdd4e6e9c49b1ef8abf3b1cd18529cafca7d9fd57240bbf0191941
 OR ISNULL((SELECT ProofCatalog FROM @CimdEvidence),0x)<>@C4aFingerprint
 OR ISNULL((SELECT ProofBefore FROM @CimdEvidence),0x)<>@C4aBefore
 THROW 59400,'CIMD proof catalog/source or predecessor drift; never refresh receipts.',1;

IF (SELECT COUNT(*) FROM sys.database_principals WHERE name IN('AiCimdCaseRuntimeV1','AiCimdLifecycleV1') AND type='R' AND owning_principal_id=1)<>2
 OR EXISTS(SELECT 1 FROM sys.database_role_members WHERE member_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdCaseRuntimeV1'),DATABASE_PRINCIPAL_ID('AiCimdLifecycleV1')))
 THROW 59400,'CIMD proof role owner/inheritance drift.',1;
DECLARE @C4aMembers table(Id int PRIMARY KEY,RoleId int);
INSERT @C4aMembers SELECT member_principal_id,role_principal_id FROM sys.database_role_members WHERE role_principal_id IN(DATABASE_PRINCIPAL_ID('AiCimdCaseRuntimeV1'),DATABASE_PRINCIPAL_ID('AiCimdLifecycleV1'));
IF EXISTS(SELECT 1 FROM @C4aMembers x JOIN sys.database_principals p ON p.principal_id=x.Id WHERE p.type<>'S' OR p.principal_id<=4)
 OR EXISTS(SELECT 1 FROM @C4aMembers x JOIN sys.database_role_members r ON r.member_principal_id=x.Id WHERE r.role_principal_id<>x.RoleId)
 OR EXISTS(SELECT 1 FROM @C4aMembers x JOIN sys.database_permissions p ON p.grantee_principal_id=x.Id WHERE NOT(p.class=0 AND p.permission_name='CONNECT' AND p.state='G'))
 OR EXISTS(SELECT 1 FROM sys.schemas WHERE principal_id IN(SELECT Id FROM @C4aMembers))
 OR EXISTS(SELECT 1 FROM sys.objects WHERE principal_id IN(SELECT Id FROM @C4aMembers))
 THROW 59400,'CIMD proof member authority drift.',1;
IF EXISTS(SELECT 1 FROM sys.crypt_properties WHERE major_id IN(SELECT OBJECT_ID('dbo.'+Name) FROM @C4aObjects))
 THROW 59400,'CIMD proof signature drift.',1;

DECLARE @C4aTokens table(Id int PRIMARY KEY);
INSERT @C4aTokens SELECT Id FROM @C4aMembers;
INSERT @C4aTokens VALUES(DATABASE_PRINCIPAL_ID('AiCimdCaseRuntimeV1')),(DATABASE_PRINCIPAL_ID('AiCimdLifecycleV1'));
IF EXISTS(SELECT 1 FROM sys.schemas WHERE principal_id IN(SELECT Id FROM @C4aTokens))
 OR EXISTS(SELECT 1 FROM sys.objects WHERE principal_id IN(SELECT Id FROM @C4aTokens))
 OR EXISTS(SELECT 1 FROM sys.database_principals WHERE owning_principal_id IN(SELECT Id FROM @C4aTokens))
 OR EXISTS(SELECT 1 FROM sys.types WHERE is_user_defined=1 AND principal_id IN(SELECT Id FROM @C4aTokens))
 OR EXISTS(SELECT 1 FROM sys.assemblies WHERE principal_id IN(SELECT Id FROM @C4aTokens))
 OR EXISTS(SELECT 1 FROM sys.certificates WHERE principal_id IN(SELECT Id FROM @C4aTokens))
 OR EXISTS(SELECT 1 FROM sys.asymmetric_keys WHERE principal_id IN(SELECT Id FROM @C4aTokens))
 THROW 59400,'CIMD proof securable ownership drift.',1;
DECLARE @C4aEdition int=CONVERT(int,SERVERPROPERTY('EngineEdition'));
IF @C4aEdition IS NULL OR @C4aEdition NOT IN(2,3,4,5,8) THROW 59400,'Unknown CIMD SQL platform.',1;
IF EXISTS(SELECT 1 FROM sys.database_principals p JOIN @C4aMembers a ON a.Id=p.principal_id WHERE p.authentication_type<>CASE WHEN @C4aEdition=5 THEN 2 ELSE 1 END)
 THROW 59400,'CIMD SQL authentication type drift.',1;
IF @C4aEdition<>5 BEGIN DECLARE @C4aServerCheck nvarchar(max)=CONVERT(nvarchar(max),); EXEC sys.sp_executesql @C4aServerCheck; END;

